mapper.select:

/*checkMasterMdCmChemicalMatInfo*/
SELECT DECODE(COUNT(A.BUYER_ITEM_NO),0,'N','Y') AS RESULT_YN
FROM KEP_CMC_RESULT A
WHERE A.BYIT_COMORG_CODE =#{st_buyer}
AND A.BUYER_ITEM_NO= #{st_buyer_item_no}

mapper.update:

		     /*cancleMasterMdCmChemicalMatByit*/
                   UPDATE KEP_CMC_BYIT A
                   SET STATUS = 'D'  
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE A.BYIT_COMORG_CODE =#{st_buyer}
                 AND A.BUYER_ITEM_NO =#{st_buyer_item_no}
                 AND A.STATUS != 'D'


		     /*cancleMasterMdCmChemicalMatMake*/
                   UPDATE KEP_CMC_BYIT_MAKE A
                   SET STATUS = 'D'  
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE A.BYIT_COMORG_CODE =#{st_buyer}
                 AND A.BUYER_ITEM_NO =#{st_buyer_item_no}
                 AND A.STATUS != 'D'


		     /*cancleMasterMdCmChemicalMatIcombyit*/
                   UPDATE ICOMBYIT A
                   SET CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
                     , MATERIAL_TYPE = ''
                 WHERE A.BUYER =#{st_buyer}
                 AND A.BUYER_ITEM_NO =#{st_buyer_item_no}
                 AND A.STATUS != 'D'

mapper.select:

/*selectMasterMdCmKepCmcByitSeq*/
SELECT NVL(COUNT(A.SEQ),0)+1  AS CMC_SEQ
FROM KEP_CMC_BYIT A 
WHERE A.BYIT_COMORG_CODE =#{st_buyer}
AND A.BUYER_ITEM_NO = #{st_buyer_item_no}

mapper.update:

/* saveMasterMdCmChemicalMatMake */
INSERT INTO KEP_CMC_BYIT_MAKE
(
	BYIT_COMORG_CODE
	, BUYER_ITEM_NO
	, SEQ
	, CMC_HARMFUL_YN
	, STATUS
	, OPEN_FLAG
	, CAS_NO
	, COMPONENT_TYPE_CODE
	, MIN_MAKE_RATE
	, MAX_MAKE_RATE
	, AVG_MAKE_RATE
	, CML_HARMFUL_YN
	, CML_PRE_TROUBLE_YN
	, CML_BAN_OBJECT_YN
	, CML_LIMIT_OBJECT_YN
	, ADD_DATE
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_USER_ID
) VALUES
(
	#{st_buyer}
	,#{st_buyer_item_no}
	, #{CMC_SEQ}
	, #{st_harmful_yn}
	, 'C'
	, #{OPEN_FLAG}
	, #{CAS_NO}
	, #{COMPONENT_TYPE_CODE}
	, #{MIN_MAKE_RATE}
	, #{MAX_MAKE_RATE}
	, #{AVG_MAKE_RATE}
	, DECODE(#{CML_HARMFUL_YN},'0','N','Y')
	, DECODE(#{CML_PRE_TROUBLE_YN},'0','N','Y')
	, DECODE(#{CML_BAN_OBJECT_YN},'0','N','Y')
	, DECODE(#{CML_LIMIT_OBJECT_YN},'0','N','Y')
	, SYSDATE
	, #{USER_ID}
	, SYSDATE
	, #{USER_ID}
)


/* saveMasterMdCmChemicalMatMake2 */
INSERT INTO KEP_CMC_BYIT_MAKE
(
	BYIT_COMORG_CODE
